/**
 * 날짜 **구간** 선택. Calendar의 단일 선택과 같은 격자를 쓰되, "지금 무엇을 고르는
 * 중인가"라는 축이 하나 더 있다.
 *
 * Calendar에 `mode: "single" | "range"`를 넣지 않은 이유: 단일 선택의 값은
 * `string | null`이고 구간의 값은 `{start, end}`다. 한 컴포넌트가 두 값 모양을 가지면
 * 모든 소비자가 매번 좁히기(narrowing)를 해야 하고, "range 모드인데 selectedDate를 준"
 * 조합이 타입에 남는다. 대신 이 모듈이 **구간 판정만** 갖고 격자는 그대로 재사용한다.
 *
 * 값은 제품이 저장한다 — 이 모듈은 다음 클릭이 시작을 바꾸는지 끝을 정하는지만 답한다.
 */
export type DateRangeValue = Readonly<{
  start: string | null;
  /** `start`만 있고 `end`가 없는 상태가 "고르는 중"이다. 별도 플래그를 두지 않는다. */
  end: string | null;
}>;

export const emptyDateRange: DateRangeValue = { start: null, end: null };

/**
 * 구간이 덮을 수 있는 최대 길이. 일수가 아니라 달력 단위로 센다 — "1년"을 365일로 두면 윤년을 낀
 * 1월 1일~12월 31일이 막힌다. 끝은 포함이라 `{ years: 1 }`은 2026-01-01부터 2026-12-31까지다.
 * 2026-10-25 사용자 요청으로 DateRangePicker 기본값은 1년이고, `null`이면 제한하지 않는다.
 */
export type DateRangeLimit = Readonly<{ years?: number; months?: number; days?: number }>;

export const defaultDateRangeLimit: DateRangeLimit = { years: 1 };

function assertDateRangeLimit(limit: DateRangeLimit): void {
  const parts = [limit.years ?? 0, limit.months ?? 0, limit.days ?? 0];
  if (parts.some((part) => !Number.isInteger(part) || part < 0) || parts.every((part) => part === 0)) {
    throw new RangeError("Date range limit must be non-negative whole years/months/days and not empty");
  }
}

function toUtc(date: string): Date {
  return new Date(Date.UTC(Number(date.slice(0, 4)), Number(date.slice(5, 7)) - 1, Number(date.slice(8, 10))));
}

function toIso(date: Date): string {
  return date.toISOString().slice(0, 10);
}

/** 달을 옮기면 그 달에 없는 날(1월 31일 + 1개월)은 말일로 맞춘다. 넘겨서 다음 달로 새지 않게 한다. */
function shiftIsoDate(date: string, limit: DateRangeLimit, sign: 1 | -1): string {
  const base = toUtc(date);
  const months = base.getUTCFullYear() * 12 + base.getUTCMonth() + sign * ((limit.years ?? 0) * 12 + (limit.months ?? 0));
  const year = Math.floor(months / 12);
  const month = months - year * 12;
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
  const shifted = new Date(Date.UTC(year, month, Math.min(base.getUTCDate(), lastDay)));
  shifted.setUTCDate(shifted.getUTCDate() + sign * (limit.days ?? 0));
  return toIso(shifted);
}

/** `start`를 한쪽 끝으로 둘 때 다른 끝이 올 수 있는 가장 이른·늦은 날(둘 다 포함). */
export function resolveDateRangeLimitBounds(start: string, limit: DateRangeLimit): Readonly<{ earliest: string; latest: string }> {
  assertIsoCalendarDate(start, "range start");
  assertDateRangeLimit(limit);
  const latest = toUtc(shiftIsoDate(start, limit, 1));
  latest.setUTCDate(latest.getUTCDate() - 1);
  const earliest = toUtc(shiftIsoDate(start, limit, -1));
  earliest.setUTCDate(earliest.getUTCDate() + 1);
  return { earliest: toIso(earliest), latest: toIso(latest) };
}

export function validateDateRange(value: DateRangeValue, limit: DateRangeLimit | null = null): void {
  if (value.start !== null) assertIsoCalendarDate(value.start, "range start");
  if (value.end !== null) assertIsoCalendarDate(value.end, "range end");
  if (value.start === null && value.end !== null) {
    throw new TypeError("Date range cannot have an end without a start");
  }
  if (value.start !== null && value.end !== null && value.end < value.start) {
    throw new RangeError("Date range end must not precede start");
  }
  if (limit !== null && value.start !== null && value.end !== null
    && value.end > resolveDateRangeLimitBounds(value.start, limit).latest) {
    throw new RangeError("Date range exceeds its maximum length");
  }
}

/**
 * 고르는 중에 이 날짜를 끝으로 고를 수 있는지. 비었거나 완성된 구간에서는 누르면 새로 시작하므로
 * 언제나 고를 수 있다. 막힌 날은 renderer가 비활성으로 그린다 — 눌렀다가 거절하면 이유를 알 수 없다.
 */
export function isDateWithinRangeLimit(value: DateRangeValue, date: string, limit: DateRangeLimit | null): boolean {
  assertIsoCalendarDate(date, "date");
  validateDateRange(value, limit);
  if (limit === null || value.start === null || value.end !== null) return true;
  const { earliest, latest } = resolveDateRangeLimitBounds(value.start, limit);
  return date >= earliest && date <= latest;
}

/**
 * 날짜 하나를 눌렀을 때의 다음 값.
 *
 * - 비어 있거나 이미 완성된 구간이면 새 구간을 **시작**한다. (완성된 구간을 다시 눌렀을
 *   때 끝을 옮기는 동작은 "어느 쪽 끝인가"를 추측해야 해서 넣지 않았다 — 다시 시작하는
 *   쪽이 예측 가능하다.)
 * - 고르는 중이면 **끝**을 정한다. 시작보다 앞선 날짜를 누르면 두 값을 바꿔 담는다 —
 *   거절하면 사용자가 왜 안 되는지 알 수 없다.
 */
export function resolveDateRangeSelection(
  current: DateRangeValue,
  date: string,
  limit: DateRangeLimit | null = null,
): DateRangeValue {
  assertIsoCalendarDate(date, "selected date");
  validateDateRange(current, limit);
  // 최대 길이를 넘는 날은 renderer가 막지만, 그래도 들어오면 넘는 구간을 만들지 않고 거기서 새로 시작한다.
  if (current.start === null || current.end !== null || !isDateWithinRangeLimit(current, date, limit)) {
    return { start: date, end: null };
  }
  return date < current.start
    ? { start: date, end: current.start }
    : { start: current.start, end: date };
}

export type DateRangeCellState = "start" | "end" | "between" | "none";

/**
 * 한 칸이 구간 안에서 어떤 자리인지. 미리보기(`hoveredDate`)는 아직 확정되지 않은 끝을
 * 가리키므로 같은 함수가 처리한다 — renderer가 두 벌의 칠하기 규칙을 만들지 않게 한다.
 */
export function resolveDateRangeCellState(
  value: DateRangeValue,
  date: string,
  hoveredDate?: string | null,
): DateRangeCellState {
  validateDateRange(value);
  if (value.start === null) return "none";
  const provisionalEnd = value.end
    ?? (hoveredDate != null && hoveredDate >= value.start ? hoveredDate : null);
  if (date === value.start && (provisionalEnd === null || date !== provisionalEnd)) return "start";
  if (provisionalEnd !== null && date === provisionalEnd) return "end";
  if (provisionalEnd !== null && date > value.start && date < provisionalEnd) return "between";
  return "none";
}

/**
 * 칸 하나를 어떻게 칠하는지. `edge`는 채운 원(시작·끝), `band`는 시작과 끝을 잇는 띠의 모양이다.
 * 띠는 시작 칸에서 끝 쪽 절반(`toEnd`), 끝 칸에서 시작 쪽 절반(`toStart`), 사이 칸 전체(`full`)를 덮는다.
 * 시작과 끝이 같은 날(하루 구간)이거나 끝이 아직 없으면 띠가 없다.
 *
 * 2026-10-25 개편(Spint 기간 시트 사용자 지적): 점 표시는 구간이 이어져 보이지 않았고, 점 줄 때문에 행이
 * 라벨 한 줄만큼 높아졌다. Material 3·Airbnb처럼 띠로 잇고 두 끝을 같은 채운 원으로 그린다.
 */
export type DateRangeCellPaint = Readonly<{ edge: boolean; band: "none" | "full" | "toEnd" | "toStart" }>;

const unpainted: DateRangeCellPaint = { edge: false, band: "none" };

export function resolveDateRangeCellPaint(
  value: DateRangeValue,
  date: string,
  hoveredDate?: string | null,
): DateRangeCellPaint {
  const state = resolveDateRangeCellState(value, date, hoveredDate);
  if (state === "none") return unpainted;
  if (state === "between") return { edge: false, band: "full" };
  const provisionalEnd = value.end
    ?? (hoveredDate != null && value.start !== null && hoveredDate >= value.start ? hoveredDate : null);
  const spans = provisionalEnd !== null && provisionalEnd !== value.start;
  if (state === "start") return { edge: true, band: spans ? "toEnd" : "none" };
  return { edge: true, band: spans ? "toStart" : "none" };
}

/**
 * 요약 칸에서 강조할 끝. 비었으면 시작, 고르는 중이면 끝을 강조한다. 완성된 구간은 아무것도 강조하지 않는다 —
 * 다음 탭이 새 시작이 되긴 하지만, 완성 직후 시작 칸이 강조되면 시작일을 고치는 중으로 읽혔다(2026-10-25 실화면).
 */
export function resolveDateRangeActiveEdge(value: DateRangeValue): "start" | "end" | null {
  validateDateRange(value);
  if (value.start === null) return "start";
  return value.end === null ? "end" : null;
}

/**
 * 프리셋 길이. `days`는 오늘 포함 n일, `months`는 n개월 전 다음 날부터 오늘까지, `all`은 날짜 제한 없음(빈 구간)이다.
 * `all`은 2026-10-28 사용자 요청("전체가 포함되게 하면 1일, 1주일, 1개월, 3개월, 전체로 하자")으로 생겼다. 필터의
 * [전체·오늘·기간 지정] 탭과 프리셋이 같은 일을 두 번 해 탭을 없애고, 전체를 프리셋 한 칸으로 옮겼다.
 */
export type DateRangePresetLength = Readonly<{ days: number } | { months: number } | { all: true }>;

const isoOf = (date: Date) => date.toISOString().slice(0, 10);

/**
 * 오늘로 끝나는 프리셋 구간(최근 7일·1개월 등). 날짜 계산은 UTC 달력 날짜로만 해 서머타임·시간대에 흔들리지 않는다.
 * 달 길이가 다르면 그 달의 마지막 날로 맞춘다(3/31의 1개월 전 = 2/28, 구간은 3/1부터).
 */
export function resolveDateRangePreset(today: string, length: DateRangePresetLength): DateRangeValue {
  assertIsoCalendarDate(today, "preset today");
  if ("all" in length) return emptyDateRange;
  const [year, month, day] = today.split("-").map(Number) as [number, number, number];
  const count = "days" in length ? length.days : length.months;
  if (!Number.isInteger(count) || count < 1) throw new RangeError("Date range preset length must be a positive integer");
  if ("days" in length) return { start: isoOf(new Date(Date.UTC(year, month - 1, day - (count - 1)))), end: today };
  const lastDay = new Date(Date.UTC(year, month - 1 - count + 1, 0)).getUTCDate();
  const anchor = new Date(Date.UTC(year, month - 1 - count, Math.min(day, lastDay)));
  anchor.setUTCDate(anchor.getUTCDate() + 1);
  return { start: isoOf(anchor), end: today };
}

export const dateRangeRecipe = {
  slots: ["root", "summary", "summaryField", "summaryLabel", "summaryValue", "presets", "band", "edge"] as const,
  // 띠는 두 끝 원과 같은 브랜드색의 tint다. 처음 쓴 `interaction.selected`(surfaceSelected)는 기본 팔레트에서
  // #f0f1f3 회색이라 시트 바탕 위에서 구간이 거의 보이지 않았다(2026-10-25 Spint 실화면). 높이는 날짜 원과 같다.
  band: { background: themeColor("primary", accentTint.base) },
  edge: calendarRecipe.day.selected,
  // 시작일·종료일 요약. 안내 문장 대신 "다음에 고를 쪽"을 강조해 지금 무엇을 누르는지 보여 준다
  // (Material 3 기간 선택 머리·Airbnb 체크인/체크아웃 칸 모티브). 값이 없으면 제품 placeholder를 쓴다.
  summary: {
    gap: spacing.xs,
    field: {
      paddingVertical: spacing.xs,
      paddingHorizontal: spacing.sm,
      radius: "md" as const,
      gap: spacing.xxs,
      background: semanticColors.surface.sunken,
      activeBorder: semanticColors.action.brand.background,
      activeBorderWidth: stroke.strong,
    },
    label: { textVariant: "label" as const, color: semanticColors.content.secondary },
    value: { textVariant: "body" as const, color: semanticColors.content.primary, placeholderColor: semanticColors.content.tertiary },
  },
  // 프리셋 칩 줄(Chip 단일 선택, 작은 크기). 요약 아래·달력 위에서 줄바꿈한다.
  presets: {
    gap: spacing.xs,
    chipSize: "small" as const,
    // 기간 필터의 표준 프리셋(2026-10-28 사용자 결정). 문구는 제품 i18n이 붙인다. 적용 버튼이 있는 시트에서는
    // `all`을 칩으로 두지 않고 BottomCTA 보조 행동(전체 날짜)으로 둔다.
    standard: [
      { id: "day", length: { days: 1 } },
      { id: "week", length: { days: 7 } },
      { id: "month", length: { months: 1 } },
      { id: "quarter", length: { months: 3 } },
      { id: "all", length: { all: true } },
    ] as const,
  },
  // 요약·프리셋·달력 사이.
  gap: spacing.md,
  // 접기(`collapsible`): 요약 줄이 펼침 버튼이 되고 끝에 방향 표시가 붙는다.
  toggle: { icon: { collapsed: "chevronDown", expanded: "chevronUp" }, glyph: "sm" as const, gap: spacing.xs },
} as const;

/**
 * 접히는 기간 선택에서 이번 선택 뒤에 달력을 계속 펼쳐 둘지. 프리셋은 언제나 접고, 날짜 탭은 구간을 완성할 때 접는다
 * (시작만 정한 첫 탭은 펼쳐 둔다). 처음에는 접힌 채 시작한다. 필터의 기본은 프리셋이고 달력은 직접 고를 때만 연다.
 *
 * 2026-10-28 사용자 "DateRangePicker도 접기 있게 해": 필터 영역에 둔 달력이 기간을 고른 뒤에도 늘 펼쳐져
 * 목록을 밀어냈다(다에리 만난 동물). Sheet·Popover 합성 없이 본문 안에서 쓰는 접힘이고, 요약 칸이 그 버튼이다.
 */
export function resolveDateRangeExpandedAfterSelection(next: DateRangeValue, source: "date" | "preset"): boolean {
  validateDateRange(next);
  return source === "date" && (next.start === null || next.end === null);
}

/** 구간이 실제로 쓸 수 있는 값인지. 제품의 제출 버튼이 읽는다. */
export function isCompleteDateRange(value: DateRangeValue): boolean {
  validateDateRange(value);
  return value.start !== null && value.end !== null;
}

